// @ts-check
'use strict'

// ─── PayPal payment provider (Orders v2 + Payments v2 + Vault v3 + Webhooks) ────
// Behind the services/payments interface. The money path (orders, captures,
// refunds, saved PayPal, memberships) runs on PayPal's official server SDK, generated by
// APIMatic (./paypalSdk.js, docs/APIMATIC.md). What the SDK doesn't
// cover (invoicing, disputes, catalog products, Log in with PayPal, partner
// onboarding, webhook verification) is plain REST below.
//
// Flow:  createCheckout() → customer approves on PayPal (payer-action link)
//        → core/paymentConfirm.finalizeOrder() re-checks the seat, THEN capture()
//        → booking confirmed. Cancel → core/refunds → refund().
// Money only moves on capture, so a slot that vanished while the customer was on
// PayPal is simply never captured — the customer is not charged.
//
// Every mutating call carries a PayPal-Request-Id so Lambda/webhook retries are
// idempotent on PayPal's side (same id → same result, no double charge/refund).
//
// Connected businesses ("Connect PayPal", Partner Referrals): the owner grants
// Flow PAYMENT + REFUND (+ invoicing) permission on their own PayPal account. Orders name the
// business as payee, so money lands in THEIR account; refunds act on their behalf
// via PayPal-Auth-Assertion. No connected account (sandbox only) → payments go to
// the platform's own sandbox account so the demo works with zero setup.

const axios = require('axios')
const sdk = require('./paypalSdk')
const { toProviderValue, round2 } = require('../../utils/money')
const trace = require('../trace')
const log = require('../../utils/logger')

const API_BASE = {
  sandbox: 'https://api-m.sandbox.paypal.com',
  live:    'https://api-m.paypal.com'
}

function env() {
  return process.env.PAYPAL_ENV === 'live' ? 'live' : 'sandbox'
}

function baseUrl() {
  return API_BASE[env()]
}

// ── OAuth2 client-credentials token, cached per Lambda container ──────────────

let tokenCache = { token: null, expiresAt: 0 }

async function accessToken() {
  if (tokenCache.token && Date.now() < tokenCache.expiresAt) return tokenCache.token
  const id = process.env.PAYPAL_CLIENT_ID
  const secret = process.env.PAYPAL_CLIENT_SECRET
  if (!id || !secret) throw new Error('PAYPAL_CLIENT_ID / PAYPAL_CLIENT_SECRET not set')

  let data
  try {
    ({ data } = await axios.post(`${baseUrl()}/v1/oauth2/token`, 'grant_type=client_credentials', {
      auth: { username: id, password: secret },
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' }
    }))
  } catch (err) {
    throw toPayPalError(err, '/v1/oauth2/token')
  }
  // Refresh a minute early so a token never expires mid-request.
  tokenCache = { token: data.access_token, expiresAt: Date.now() + (Number(data.expires_in) - 60) * 1000 }
  return tokenCache.token
}

function _resetTokenCache() { tokenCache = { token: null, expiresAt: 0 }; sdk._reset() }

async function call(method, path, { body, requestId, headers: extra } = {}) {
  const headers = {
    Authorization:  `Bearer ${await accessToken()}`,
    'Content-Type': 'application/json',
    Prefer:         'return=representation',
    ...(process.env.PAYPAL_BN_CODE ? { 'PayPal-Partner-Attribution-Id': process.env.PAYPAL_BN_CODE } : {}),
    ...(extra || {})
  }
  if (requestId) headers['PayPal-Request-Id'] = requestId
  try {
    const { data } = await axios({ method, url: `${baseUrl()}${path}`, data: body, headers })
    return data
  } catch (err) {
    throw toPayPalError(err, path)
  }
}

// Normalise PayPal's error body ({name, details[{issue}], debug_id}) into an Error
// whose .code is the first issue (e.g. ORDER_ALREADY_CAPTURED) so callers branch on it.
function toPayPalError(err, path) {
  const data = err.response?.data
  const issue = data?.details?.[0]?.issue || data?.name || data?.error || 'PAYPAL_ERROR'
  const e = new Error(`PayPal ${err.response?.status || ''} ${issue} on ${path}`.trim())
  Object.assign(e, { code: issue, status: err.response?.status, debugId: data?.debug_id })
  log.warn('paypal_api_error', { path, status: e.status, issue, debugId: e.debugId })
  return e
}

// ── Provider interface ───────────────────────────────────────────────────────

// Platform keys present, and — in live — the business has connected its own
// PayPal (Flow never collects real money into the platform account).
function isConfigured(business) {
  if (!(process.env.PAYPAL_CLIENT_ID && process.env.PAYPAL_CLIENT_SECRET)) return false
  return env() === 'sandbox' || !!business?.paypalMerchantId
}

// Unsigned JWT that lets the platform act on a connected merchant's account
// (used for refunds of captures that landed in the business's PayPal).
function authAssertion(merchantId) {
  const b64 = o => Buffer.from(JSON.stringify(o)).toString('base64url')
  return `${b64({ alg: 'none' })}.${b64({ iss: process.env.PAYPAL_CLIENT_ID, payer_id: merchantId })}.`
}

/**
 * Create a CAPTURE-intent order and return the link the customer approves on.
 * referenceId is our own id (stored as custom_id so webhooks can be traced back).
 */
async function createCheckout({ referenceId, amount, currency, description, business, returnUrl, cancelUrl, saveForLater }) {
  const E = sdk.lib()
  const unit = purchaseUnit({ referenceId, amount, currency, description, business })
  const paypal = {
    experienceContext: {
      brandName:          (business?.name || 'Flow').slice(0, 127),
      userAction:         E.PaypalExperienceUserAction.PayNow,
      shippingPreference: E.PaypalWalletContextShippingPreference.NoShipping,
      landingPage:        E.PaypalExperienceLandingPage.Login,
      returnUrl,
      cancelUrl
    }
  }
  // "Save payment methods": PayPal asks the buyer to agree on its own page, and
  // the capture response then carries the saved account's vault id.
  if (saveForLater) {
    paypal.attributes = { vault: {
      storeInVault: E.StoreInVaultInstruction.OnSuccess,
      usageType:    E.PaypalPaymentTokenUsageType.Merchant,
      customerType: E.PaypalPaymentTokenCustomerType.Consumer
    } }
  }
  const order = await sdk.run('orders.createOrder', () => sdk.orders().createOrder({
    body: { intent: E.CheckoutPaymentIntent.Capture, purchaseUnits: [unit], paymentSource: { paypal } },
    paypalRequestId: `ord_${referenceId}`,
    prefer: 'return=representation',
    paypalPartnerAttributionId: process.env.PAYPAL_BN_CODE || undefined
  }))
  const approve = link(order, 'payer-action', 'approve')
  if (!approve) throw new Error(`PayPal order ${order.id} has no approve link`)
  return { providerOrderId: order.id, approveUrl: approve, status: order.status }
}

// The SDK's PurchaseUnitRequest (camelCase; it writes PayPal's snake_case JSON).
function purchaseUnit({ referenceId, amount, currency, description, business }) {
  const unit = {
    referenceId:    referenceId.slice(0, 256),
    customId:       referenceId.slice(0, 127),
    description:    (description || 'Booking').slice(0, 127),
    softDescriptor: (business?.name || 'Flow').replace(/[^A-Za-z0-9 ]/g, '').slice(0, 22) || undefined,
    amount:         { currencyCode: currency, value: toProviderValue(amount, currency) }
  }
  // A business with its own PayPal account gets paid directly.
  if (business?.paypalMerchantId) unit.payee = { merchantId: business.paypalMerchantId }
  return unit
}

const link = (resource, ...rels) => (resource?.links || []).find(l => rels.includes(l.rel))?.href || null

/**
 * Pay with a customer's saved PayPal (no PayPal page). PayPal usually captures
 * at once (COMPLETED); an order that still needs the buyer comes back with its
 * approve link so the caller can fall back to the normal flow.
 */
async function chargeSaved({ referenceId, amount, currency, description, business, vaultId, returnUrl, cancelUrl, initiator = 'CUSTOMER', usagePattern, clientMetadataId, invoiceId }) {
  const E = sdk.lib()
  const unit = purchaseUnit({ referenceId, amount, currency, description, business })
  if (invoiceId) unit.invoiceId = String(invoiceId).slice(0, 127)
  const order = await sdk.run('orders.createOrder (saved PayPal)', () => sdk.orders().createOrder({
    body: {
      intent: E.CheckoutPaymentIntent.Capture,
      purchaseUnits: [unit],
      paymentSource: { paypal: {
        vaultId,
        // Who started it: the customer saying yes (CUSTOMER), or Flow charging
        // under terms they agreed to earlier (MERCHANT: the AI mandate, a renewal).
        storedCredential: {
          paymentInitiator: initiator === 'MERCHANT' ? E.PaymentInitiator.Merchant : E.PaymentInitiator.Customer,
          ...(usagePattern ? { usagePattern } : {})   // a UsagePattern value, e.g. UNSCHEDULED_PREPAID
        },
        experienceContext: { returnUrl, cancelUrl, shippingPreference: E.PaypalWalletContextShippingPreference.NoShipping }
      } }
    },
    paypalRequestId: `ordv_${referenceId}`,
    prefer: 'return=representation',
    paypalPartnerAttributionId: process.env.PAYPAL_BN_CODE || undefined,
    // Risk data (FraudNet) for a customer-started charge from a browser.
    paypalClientMetadataId: clientMetadataId && initiator === 'CUSTOMER' ? clientMetadataId : undefined
  }))
  return {
    providerOrderId: order.id, status: order.status,
    captured: order.status === 'COMPLETED' ? captureFromOrder(order) : null,
    approveUrl: order.status === 'PAYER_ACTION_REQUIRED' ? link(order, 'payer-action', 'approve') : null
  }
}

// ── Log in with PayPal (the demo customer signs in: core/paypalLogin) ─────────

// Login can run on its own PayPal app (PAYPAL_LOGIN_CLIENT_ID / _SECRET): Log in with
// PayPal is a per-app feature, and payments stay on Flow's main app either way.
function loginApp() {
  const own = process.env.PAYPAL_LOGIN_CLIENT_ID && process.env.PAYPAL_LOGIN_CLIENT_SECRET
  return own
    ? { id: process.env.PAYPAL_LOGIN_CLIENT_ID, secret: process.env.PAYPAL_LOGIN_CLIENT_SECRET }
    : { id: process.env.PAYPAL_CLIENT_ID || '', secret: process.env.PAYPAL_CLIENT_SECRET || '' }
}

function loginUrl({ redirectUri, state }) {
  const web = env() === 'live' ? 'https://www.paypal.com' : 'https://www.sandbox.paypal.com'
  const q = new URLSearchParams({ flowEntry: 'static', client_id: loginApp().id, response_type: 'code', scope: 'openid profile email', redirect_uri: redirectUri, state })
  return `${web}/connect?${q.toString().replace(/\+/g, '%20')}`
}

/** Swap the login code for the customer's name, email and payer id. The token isn't kept. */
async function loginUser(code) {
  let token
  try {
    ({ data: token } = await axios.post(`${baseUrl()}/v1/oauth2/token`, new URLSearchParams({ grant_type: 'authorization_code', code }).toString(), {
      auth: { username: loginApp().id, password: loginApp().secret },
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' }
    }))
  } catch (err) {
    throw toPayPalError(err, '/v1/oauth2/token (login)')
  }
  let info
  try {
    ({ data: info } = await axios.get(`${baseUrl()}/v1/identity/oauth2/userinfo?schema=paypalv1.1`, { headers: { Authorization: `Bearer ${token.access_token}` } }))
  } catch (err) {
    throw toPayPalError(err, '/v1/identity/oauth2/userinfo')
  }
  const email = (info.emails || []).find(e => e.primary)?.value || info.emails?.[0]?.value || info.email || null
  const name = info.name || [info.given_name, info.family_name].filter(Boolean).join(' ') || null
  return { name, email, payerId: info.payer_id || null }
}

// ── Saved PayPal (Vault v3) ──────────────────────────────────────────────────
// Saving without paying ("Change account"): a setup token the customer approves
// on PayPal, then exchanged for a payment token (the vault id).

async function createVaultSetup({ requestId, returnUrl, cancelUrl, brandName }) {
  const E = sdk.lib()
  const t = await sdk.run('vault.createSetupToken', () => sdk.vault().createSetupToken({
    body: { paymentSource: { paypal: {
      usageType: E.PaypalPaymentTokenUsageType.Merchant,
      customerType: E.PaypalPaymentTokenCustomerType.Consumer,
      permitMultiplePaymentTokens: false,
      experienceContext: {
        brandName: (brandName || 'Flow').slice(0, 127),
        shippingPreference: E.ExperienceContextShippingPreference.NoShipping,
        returnUrl, cancelUrl
      }
    } } },
    paypalRequestId: `setup_${requestId}`
  }))
  const approve = link(t, 'approve')
  if (!approve) throw new Error(`PayPal setup token ${t.id} has no approve link`)
  return { setupTokenId: t.id, approveUrl: approve }
}

async function finishVaultSetup(setupTokenId) {
  const E = sdk.lib()
  const t = await sdk.run('vault.createPaymentToken', () => sdk.vault().createPaymentToken({
    body: { paymentSource: { token: { id: setupTokenId, type: E.VaultTokenRequestType.SetupToken } } },
    paypalRequestId: `ptok_${setupTokenId}`
  }))
  return { vaultId: t.id, email: t.paymentSource?.paypal?.emailAddress || null }
}

// Already gone at PayPal counts as removed.
async function deleteSaved(vaultId) {
  try {
    await sdk.run('vault.deletePaymentToken', () => sdk.vault().deletePaymentToken(vaultId))
  } catch (err) {
    if (err.status !== 404) throw err
  }
  return { removed: true }
}

// Pull the first capture out of the SDK's Order.
function captureFromOrder(order) {
  const pu = order.purchaseUnits?.[0]
  const cap = pu?.payments?.captures?.[0]
  return {
    providerOrderId: order.id,
    status:     order.status,                      // CREATED | APPROVED | COMPLETED | ...
    captureId:  cap?.id || null,
    captureStatus: cap?.status || null,            // COMPLETED | PENDING | DECLINED ...
    amount:     cap?.amount ? round2(cap.amount.value) : (pu?.amount ? round2(pu.amount.value) : null),
    currency:   cap?.amount?.currencyCode || pu?.amount?.currencyCode || null,
    paidAt:     cap?.createTime || null,
    referenceId: pu?.customId || pu?.referenceId || null,
    payeeMerchantId: pu?.payee?.merchantId || null,
    payerEmail: order.payer?.emailAddress || order.paymentSource?.paypal?.emailAddress || null,
    payerName:  [order.payer?.name?.givenName, order.payer?.name?.surname].filter(Boolean).join(' ') || null,
    // Set when the buyer agreed to save PayPal on this payment (store_in_vault).
    savedPaypal: savedFromOrder(order)
  }
}

function savedFromOrder(order) {
  const pp = order.paymentSource?.paypal
  const vault = pp?.attributes?.vault
  if (!vault?.id || (vault.status && vault.status !== 'VAULTED')) return null
  return { vaultId: vault.id, email: pp.emailAddress || order.payer?.emailAddress || null }
}

async function getOrder(providerOrderId) {
  return captureFromOrder(await sdk.run('orders.getOrder', () => sdk.orders().getOrder({ id: providerOrderId })))
}

/**
 * Capture an approved order. Idempotent: a retry with the same request id, or an
 * order someone else already captured, returns the existing capture.
 */
async function capture(providerOrderId) {
  try {
    const order = await sdk.run('orders.captureOrder', () => sdk.orders().captureOrder({
      id: providerOrderId,
      paypalRequestId: `cap_${providerOrderId}`,
      prefer: 'return=representation'
    }))
    return captureFromOrder(order)
  } catch (err) {
    if (err.code === 'ORDER_ALREADY_CAPTURED') return getOrder(providerOrderId)
    throw err
  }
}

// ── Subscriptions (memberships: core/memberships) ───────────────────────────
// A membership plan = a PayPal catalog product + a monthly billing plan. The
// customer approves a subscription; PayPal then bills them every month. In the
// sandbox demo the plans live on the platform account (a connected business
// would need PayPal's partner permissions for subscriptions on its behalf).

async function createMembershipPlan({ name, price, currency, businessName, requestId }) {
  // Catalog Products isn't in the SDK: the product is plain REST, the plan isn't.
  const product = await call('post', '/v1/catalogs/products', {
    requestId: `prod_${requestId}`,
    body: { name: `${businessName}: ${name}`.slice(0, 127), type: 'SERVICE', category: 'BEAUTY_AND_FRAGRANCES' }
  })
  const E = sdk.lib()
  const plan = await sdk.run('subscriptions.createBillingPlan', () => sdk.subscriptions().createBillingPlan({
    body: {
      productId: product.id,
      name: name.slice(0, 127),
      status: E.PlanRequestStatus.Active,
      billingCycles: [{
        frequency: { intervalUnit: E.IntervalUnit.Month, intervalCount: 1 },
        tenureType: E.TenureType.Regular, sequence: 1, totalCycles: 0,
        pricingScheme: { fixedPrice: { currencyCode: currency, value: toProviderValue(price, currency) } }
      }],
      paymentPreferences: { autoBillOutstanding: true, paymentFailureThreshold: 1 }
    },
    paypalRequestId: `plan_${requestId}`,
    prefer: 'return=representation'
  }))
  return { productId: product.id, planId: plan.id }
}

/** customId comes back on every webhook, so events find the membership. */
async function createSubscription({ planId, customId, businessName, returnUrl, cancelUrl }) {
  const E = sdk.lib()
  const sub = await sdk.run('subscriptions.createSubscription', () => sdk.subscriptions().createSubscription({
    body: {
      planId,
      customId: customId.slice(0, 127),
      applicationContext: {
        brandName: (businessName || 'Flow').slice(0, 127),
        userAction: E.ApplicationContextUserAction.SubscribeNow,
        shippingPreference: E.ExperienceContextShippingPreference.NoShipping,
        returnUrl, cancelUrl
      }
    },
    paypalRequestId: `sub_${customId}`.slice(0, 108),
    prefer: 'return=representation'
  }))
  const approve = link(sub, 'approve')
  if (!approve) throw new Error(`PayPal subscription ${sub.id} has no approve link`)
  return { subscriptionId: sub.id, approveUrl: approve, status: sub.status }
}

async function getSubscription(subscriptionId) {
  const s = await sdk.run('subscriptions.getSubscription', () => sdk.subscriptions().getSubscription({ id: subscriptionId }))
  const last = s.billingInfo?.lastPayment
  return {
    subscriptionId: s.id, status: s.status, planId: s.planId, customId: s.customId || null,
    nextBillingTime: s.billingInfo?.nextBillingTime || null,
    lastPayment: last ? { amount: round2(last.amount?.value), time: last.time } : null,
    failedPayments: s.billingInfo?.failedPaymentsCount || 0,
    payerEmail: s.subscriber?.emailAddress || null
  }
}

async function cancelSubscription(subscriptionId, reason) {
  await sdk.run('subscriptions.cancelSubscription', () => sdk.subscriptions().cancelSubscription({
    id: subscriptionId,
    body: { reason: String(reason || 'Cancelled by the customer').slice(0, 127) }
  }))
  return { subscriptionId, status: 'CANCELLED' }
}

/**
 * Refund a capture (full when amount is omitted, otherwise partial). requestId
 * must be stable per logical refund (e.g. ref_{appointmentId}) so a retried
 * cancellation can never refund twice.
 */
async function refund({ captureId, amount, currency, requestId, note, merchantId }) {
  const body = {}
  if (amount != null) body.amount = { currencyCode: currency, value: toProviderValue(amount, currency) }
  if (note) body.noteToPayer = String(note).slice(0, 255)
  const r = await sdk.run('payments.refundCapturedPayment', () => sdk.payments().refundCapturedPayment({
    captureId, body,
    paypalRequestId: requestId,
    prefer: 'return=representation',
    // Money sits in the business's own PayPal → refund on their behalf.
    paypalAuthAssertion: merchantId ? authAssertion(merchantId) : undefined
  }))
  return {
    refundId: r.id,
    status:   r.status,                            // COMPLETED | PENDING | CANCELLED | FAILED
    amount:   r.amount ? round2(r.amount.value) : amount,
    currency: r.amount?.currencyCode || currency
  }
}

async function getRefund(refundId) {
  const r = await sdk.run('payments.getRefund', () => sdk.payments().getRefund({ refundId }))
  return { refundId: r.id, status: r.status, amount: round2(r.amount?.value), currency: r.amount?.currencyCode }
}

/**
 * PayPal's own record of one payment, for the owner: gross, PayPal's fee, net,
 * and every refund. Read with the platform's credentials (Flow created the
 * order), so the owner never needs a PayPal token. Prefers the order (it lists
 * refunds); a booking with only a capture id falls back to the capture.
 */
async function getPayment({ providerOrderId, captureId }) {
  const money = v => (v?.value != null ? round2(v.value) : null)
  if (providerOrderId) {
    const order = await sdk.run('orders.getOrder', () => sdk.orders().getOrder({ id: providerOrderId }))
    const pu = order.purchaseUnits?.[0] || {}
    const brk = pu.payments?.captures?.[0]?.sellerReceivableBreakdown
    const refunds = (pu.payments?.refunds || []).map(r => ({ refundId: r.id, status: r.status, amount: money(r.amount), createdAt: r.createTime || null }))
    return {
      ...captureFromOrder(order),
      fee: money(brk?.paypalFee),
      net: money(brk?.netAmount),
      refunds,
      refundedTotal: round2(refunds.filter(r => r.status !== 'CANCELLED' && r.status !== 'FAILED').reduce((s, r) => s + (r.amount || 0), 0))
    }
  }
  const c = await sdk.run('payments.getCapturedPayment', () => sdk.payments().getCapturedPayment({ captureId }))
  return {
    providerOrderId: c.supplementaryData?.relatedIds?.orderId || null,
    status: null,
    captureId: c.id,
    captureStatus: c.status,
    amount: money(c.amount),
    currency: c.amount?.currencyCode || null,
    paidAt: c.createTime || null,
    payeeMerchantId: c.payee?.merchantId || null,
    fee: money(c.sellerReceivableBreakdown?.paypalFee),
    net: money(c.sellerReceivableBreakdown?.netAmount),
    refunds: null,          // the capture alone doesn't list refunds
    refundedTotal: null
  }
}

// ── Invoicing ───────────────────────────────────
// A paid invoice per booking or pack, in the PayPal account that received the
// money: the connected business (on its behalf, like refunds) or the platform's
// sandbox account. PayPal sends it to nobody: the Flow inbox carries the receipt PDF.

const onBehalf = merchantId => (merchantId ? { 'PayPal-Auth-Assertion': authAssertion(merchantId) } : undefined)
const money2 = (amount, currency) => ({ currency_code: currency, value: toProviderValue(amount, currency) })
const ymd = d => new Date(d || Date.now()).toISOString().slice(0, 10)

function invoiceView(inv) {
  const md = inv.detail?.metadata || {}
  const num = v => (v?.value != null ? round2(v.value) : null)
  return {
    invoiceId:   inv.id,
    number:      inv.detail?.invoice_number || null,
    status:      inv.status || null,     // DRAFT | SENT | UNPAID | PAID | MARKED_AS_PAID | PARTIALLY_PAID | REFUNDED | PARTIALLY_REFUNDED | MARKED_AS_REFUNDED | CANCELLED
    total:       num(inv.amount),
    paid:        num(inv.payments?.paid_amount),
    refunded:    num(inv.refunds?.refund_amount),
    due:         num(inv.due_amount),
    currency:    inv.amount?.currency_code || inv.detail?.currency_code || null,
    recipientUrl: md.recipient_view_url || null,
    invoicerUrl:  md.invoicer_view_url || null,
    reference:   inv.detail?.reference || null,
    date:        inv.detail?.invoice_date || null
  }
}

/**
 * Create a draft invoice. `lines` are { name, description?, amount } (quantity 1).
 * requestId keeps a retried call from creating a second invoice.
 */
async function createInvoice({ merchantId, invoicerEmail, businessName, customer, lines, currency, reference, note, terms, requestId }) {
  const [given, ...rest] = String(customer?.name || 'Customer').trim().split(/\s+/)
  const body = {
    detail: {
      currency_code: currency,
      reference:     String(reference || '').slice(0, 120) || undefined,
      invoice_date:  ymd(),
      note:          note ? String(note).slice(0, 4000) : undefined,
      terms_and_conditions: terms ? String(terms).slice(0, 4000) : undefined,
      payment_term:  { term_type: 'DUE_ON_RECEIPT' }
    },
    invoicer: { business_name: String(businessName || 'Flow').slice(0, 300), ...(invoicerEmail ? { email_address: invoicerEmail } : {}) },
    primary_recipients: customer?.email ? [{ billing_info: { name: { given_name: given, ...(rest.length ? { surname: rest.join(' ') } : {}) }, email_address: customer.email } }] : undefined,
    items: lines.map(l => ({ name: String(l.name).slice(0, 200), ...(l.description ? { description: String(l.description).slice(0, 1000) } : {}), quantity: '1', unit_amount: money2(l.amount, currency), unit_of_measure: 'QUANTITY' })),
    configuration: { allow_tip: false, partial_payment: { allow_partial_payment: true } }
  }
  const inv = await call('post', '/v2/invoicing/invoices', { body, requestId, headers: onBehalf(merchantId) })
  // Some accounts answer with only a link; read the invoice back for its number and links.
  return invoiceView(inv.detail ? inv : await call('get', new URL(inv.href).pathname, { headers: onBehalf(merchantId) }))
}

/** Draft → unpaid, without PayPal emailing anyone. */
async function sendInvoice({ merchantId, invoiceId, requestId }) {
  await call('post', `/v2/invoicing/invoices/${encodeURIComponent(invoiceId)}/send`, { requestId, body: { send_to_invoicer: false, send_to_recipient: false }, headers: onBehalf(merchantId) })
}

/** Record a PayPal payment we already captured: unpaid → paid or partly paid. */
async function recordInvoicePayment({ merchantId, invoiceId, amount, currency, paidAt, captureId, requestId }) {
  const r = await call('post', `/v2/invoicing/invoices/${encodeURIComponent(invoiceId)}/payments`, {
    requestId, headers: onBehalf(merchantId),
    body: { method: 'PAYPAL', payment_date: ymd(paidAt), amount: money2(amount, currency), note: captureId ? `PayPal payment ${captureId}` : undefined }
  })
  return { paymentId: r?.payment_id || null }
}

/** Record a refund we already made through PayPal: → refunded or partly refunded. */
async function recordInvoiceRefund({ merchantId, invoiceId, amount, currency, refundedAt, requestId }) {
  const r = await call('post', `/v2/invoicing/invoices/${encodeURIComponent(invoiceId)}/refunds`, {
    requestId, headers: onBehalf(merchantId),
    body: { method: 'PAYPAL', refund_date: ymd(refundedAt), amount: money2(amount, currency) }
  })
  return { refundId: r?.refund_id || null }
}

async function getInvoice({ merchantId, invoiceId }) {
  return invoiceView(await call('get', `/v2/invoicing/invoices/${encodeURIComponent(invoiceId)}`, { headers: onBehalf(merchantId) }))
}

// ── Connect PayPal (Partner Referrals onboarding) ────────────────────────────

/**
 * Link the owner opens to connect their PayPal business account to Flow and
 * grant PAYMENT + REFUND + INVOICE_READ_WRITE. tracking_id = our businessId (comes back on return).
 */
// ── Disputes (core/disputes §4) ───────────────

function disputeView(d) {
  const tx = d.disputed_transactions?.[0] || {}
  return {
    disputeId: d.dispute_id, status: d.status, reason: d.reason, stage: d.dispute_life_cycle_stage || null,
    amount: Number(d.dispute_amount?.value || 0), currency: d.dispute_amount?.currency_code || 'USD',
    captureId: tx.seller_transaction_id || null, createdAt: d.create_time || null, updatedAt: d.update_time || null,
    dueAt: d.seller_response_due_date || null, outcome: d.dispute_outcome?.outcome_code || null,
    offerAmount: d.offer?.buyer_requested_amount?.value ? Number(d.offer.buyer_requested_amount.value) : null,
    buyerMessage: (d.messages || []).filter(m => m.posted_by === 'BUYER').map(m => m.content).pop() || null
  }
}

async function listDisputes({ startTime } = {}) {
  const q = new URLSearchParams({ page_size: '50', ...(startTime ? { start_time: startTime } : {}) })
  const data = await call('get', `/v1/customer/disputes?${q}`)
  return (data.items || []).map(d => d.dispute_id)
}

async function getDispute(disputeId) {
  return disputeView(await call('get', `/v1/customer/disputes/${encodeURIComponent(disputeId)}`))
}

// Evidence and claims are multipart: a JSON "input" part, plus files.
async function multipart(path, input, files = []) {
  const form = new FormData()
  form.append('input', new Blob([JSON.stringify(input)], { type: 'application/json' }), 'input.json')
  for (const f of files) form.append(f.field, new Blob([f.data], { type: f.contentType }), f.filename)
  const res = await fetch(`${baseUrl()}${path}`, { method: 'POST', headers: { Authorization: `Bearer ${await accessToken()}` }, body: form })
  const data = await res.json().catch(() => ({}))
  if (!res.ok) throw toPayPalError({ response: { status: res.status, data } }, path)
  return data
}

/** The seller's response: notes plus the booking timeline as a PDF. */
async function provideDisputeEvidence({ disputeId, evidenceType, notes, pdf }) {
  await multipart(`/v1/customer/disputes/${encodeURIComponent(disputeId)}/provide-evidence`,
    { evidences: [{ evidence_type: evidenceType, notes: String(notes).slice(0, 2000) }] },
    pdf ? [{ field: 'evidence-file', data: pdf, contentType: 'application/pdf', filename: 'booking-timeline.pdf' }] : [])
  return { sent: true }
}

async function acceptDisputeClaim({ disputeId, note }) {
  await multipart(`/v1/customer/disputes/${encodeURIComponent(disputeId)}/accept-claim`, { note: String(note || 'The business accepts the claim.').slice(0, 2000) })
  return { accepted: true }
}

/** Sandbox only: move a case on (ask for evidence) or decide it, for testing. */
async function sandboxDispute({ disputeId, action }) {
  if (env() !== 'sandbox') throw new Error('Only in the PayPal sandbox')
  const id = encodeURIComponent(disputeId)
  if (action === 'require_evidence') await call('post', `/v1/customer/disputes/${id}/require-evidence`, { body: { action: 'SELLER_EVIDENCE' } })
  else await call('post', `/v1/customer/disputes/${id}/adjudicate`, { body: { adjudication_outcome: action === 'seller_wins' ? 'SELLER_FAVOR' : 'BUYER_FAVOR' } })
  return { done: true }
}

async function createOnboardingLink({ businessId, returnUrl, email }) {
  const r = await call('post', '/v2/customer/partner-referrals', {
    body: {
      tracking_id: businessId,
      ...(email ? { email } : {}),
      operations: [{
        operation: 'API_INTEGRATION',
        api_integration_preference: {
          rest_api_integration: {
            integration_method: 'PAYPAL',
            integration_type:   'THIRD_PARTY',
            third_party_details: { features: ['PAYMENT', 'REFUND', 'INVOICE_READ_WRITE', 'ACCESS_MERCHANT_INFORMATION'] }
          }
        }
      }],
      products: ['EXPRESS_CHECKOUT'],
      legal_consents: [{ type: 'SHARE_DATA_CONSENT', granted: true }],
      partner_config_override: { return_url: returnUrl, return_url_description: 'Back to Flow' }
    }
  })
  const link = (r.links || []).find(l => l.rel === 'action_url')
  if (!link) throw new Error('PayPal partner referral returned no action_url')
  return { url: link.href }
}

/**
 * Ask PayPal what a connected merchant actually granted. Needs the platform's own
 * merchant id (PAYPAL_PARTNER_MERCHANT_ID). Returns null when that isn't set so the
 * caller can fall back to the return-URL params (sandbox demo).
 */
async function getMerchantStatus(merchantId) {
  const partner = process.env.PAYPAL_PARTNER_MERCHANT_ID
  if (!partner) return null
  const m = await call('get', `/v1/customer/partners/${encodeURIComponent(partner)}/merchant-integrations/${encodeURIComponent(merchantId)}`)
  const scopes = (m.oauth_integrations || []).flatMap(o => (o.oauth_third_party || []).flatMap(t => t.scopes || []))
  return {
    merchantId:         m.merchant_id,
    trackingId:         m.tracking_id || null,
    paymentsReceivable: m.payments_receivable !== false,
    emailConfirmed:     m.primary_email_confirmed !== false,
    email:              m.primary_email || null,
    canRefund:          scopes.some(sc => /refund/i.test(sc)),
    canInvoice:         scopes.some(sc => /invoic/i.test(sc)),
    scopes
  }
}

/**
 * Verify a webhook with PayPal's verify-webhook-signature API. The raw body is
 * spliced in verbatim (not re-serialised) — re-stringifying a parsed event can
 * reorder/reformat fields and make a genuine event fail verification.
 */
async function verifyWebhook(headers, rawBody) {
  const h = lowerKeys(headers)
  const webhookId = process.env.PAYPAL_WEBHOOK_ID
  if (!webhookId || !rawBody || !h['paypal-transmission-sig']) return false
  const meta = {
    auth_algo:         h['paypal-auth-algo'],
    cert_url:          h['paypal-cert-url'],
    transmission_id:   h['paypal-transmission-id'],
    transmission_sig:  h['paypal-transmission-sig'],
    transmission_time: h['paypal-transmission-time'],
    webhook_id:        webhookId
  }
  const body = `${JSON.stringify(meta).slice(0, -1)},"webhook_event":${rawBody}}`
  try {
    const { data } = await axios.post(`${baseUrl()}/v1/notifications/verify-webhook-signature`, body, {
      headers: { Authorization: `Bearer ${await accessToken()}`, 'Content-Type': 'application/json' }
    })
    return data?.verification_status === 'SUCCESS'
  } catch (err) {
    log.warn('paypal_webhook_verify_failed', { status: err.response?.status })
    return false
  }
}

function lowerKeys(obj) {
  const out = {}
  for (const [k, v] of Object.entries(obj || {})) out[k.toLowerCase()] = v
  return out
}

// Public functions are traced for the "Under the hood" timeline (no-op outside a scope).
const traced = (title, fn, sum) => (...args) => trace.span('paypal', title, () => fn(...args), r => sum(r, args[0] || {}))
// Steps that run on the APIMatic-generated SDK say so on the timeline.
const viaSdk = (title, fn, sum) => traced(title, fn, (r, a) => ({ ...sum(r, a), via: sdk.VIA }))
const S = trace.short

module.exports = {
  id: 'paypal',
  isConfigured,
  createCheckout: viaSdk('PayPal: order created', createCheckout, (r, a) => ({ order: S(r.providerOrderId), amount: `${a.amount} ${a.currency}`, payee: a.business?.paypalMerchantId ? 'business PayPal' : 'platform sandbox', intent: 'CAPTURE' })),
  capture:        viaSdk('PayPal: payment captured', capture, r => ({ capture: S(r.captureId), status: r.captureStatus, amount: `${r.amount} ${r.currency}`, idempotencyKey: 'cap_<order>' })),
  getOrder,
  chargeSaved:    viaSdk('PayPal: paid with saved PayPal', chargeSaved, (r, a) => ({
    order: S(r.providerOrderId), amount: `${a.amount} ${a.currency}`, status: r.status,
    startedBy: (a.initiator || 'CUSTOMER') === 'CUSTOMER' ? 'the customer (CUSTOMER)' : `Flow under agreed terms (MERCHANT${a.usagePattern ? `, ${a.usagePattern}` : ''})`,
    ...(a.clientMetadataId && (a.initiator || 'CUSTOMER') === 'CUSTOMER' ? { riskData: 'sent' } : {}),
    ...(a.invoiceId ? { mandate: a.invoiceId } : {}),
    buyerOnPayPal: r.approveUrl ? 'needed again' : 'not needed'
  })),
  createVaultSetup: viaSdk('PayPal: link to save PayPal created', createVaultSetup, r => ({ setupToken: S(r.setupTokenId), payment: 'none' })),
  finishVaultSetup: viaSdk('PayPal: PayPal saved', finishVaultSetup, r => ({ saved: S(r.vaultId) })),
  deleteSaved:    viaSdk('PayPal: saved PayPal removed', deleteSaved, (r, a) => ({ saved: S(a) })),
  loginUrl,
  loginUser:      traced('PayPal: customer logged in with PayPal', loginUser, r => ({ name: r.name ? 'shared' : 'not shared', email: r.email ? 'shared' : 'not shared' })),
  refund:        viaSdk('PayPal: refund issued', refund, (r, a) => ({ refund: S(r.refundId), status: r.status, amount: `${r.amount} ${r.currency}`, onBehalfOfBusiness: !!a.merchantId, idempotencyKey: a.requestId })),
  getRefund,
  getPayment:     viaSdk('PayPal: payment looked up', getPayment, r => ({ order: S(r.providerOrderId), capture: S(r.captureId), status: r.captureStatus, fee: r.fee, refunds: r.refunds ? r.refunds.length : 'n/a' })),
  verifyWebhook,
  createOnboardingLink: traced('PayPal: onboarding link created', createOnboardingLink, () => ({ permissions: 'PAYMENT + REFUND + INVOICE_READ_WRITE' })),
  createInvoice:  traced('PayPal: invoice created', createInvoice, (r, a) => ({ invoice: r.number, total: `${r.total} ${r.currency}`, account: a.merchantId ? 'business PayPal' : 'platform sandbox' })),
  sendInvoice:    traced('PayPal: invoice issued (PayPal sends it to nobody)', sendInvoice, (r, a) => ({ invoice: S(a.invoiceId) })),
  recordInvoicePayment: traced('PayPal: payment recorded on the invoice', recordInvoicePayment, (r, a) => ({ invoice: S(a.invoiceId), amount: `${a.amount} ${a.currency}`, capture: S(a.captureId) })),
  recordInvoiceRefund:  traced('PayPal: refund recorded on the invoice', recordInvoiceRefund, (r, a) => ({ invoice: S(a.invoiceId), amount: `${a.amount} ${a.currency}` })),
  getInvoice:     traced('PayPal: invoice looked up', getInvoice, r => ({ invoice: r.number, status: r.status })),
  createMembershipPlan: viaSdk('PayPal: membership plan created', createMembershipPlan, (r, a) => ({ plan: S(r.planId), price: `${a.price} ${a.currency} a month` })),
  createSubscription: viaSdk('PayPal: subscription created', createSubscription, r => ({ subscription: S(r.subscriptionId), status: r.status })),
  getSubscription: viaSdk('PayPal: subscription checked', getSubscription, r => ({ subscription: S(r.subscriptionId), status: r.status, nextBilling: r.nextBillingTime })),
  cancelSubscription: viaSdk('PayPal: subscription cancelled', cancelSubscription, r => ({ subscription: S(r.subscriptionId) })),
  listDisputes:   traced('PayPal: disputes listed', listDisputes, r => ({ cases: r.length })),
  getDispute:     traced('PayPal: dispute looked up', getDispute, r => ({ dispute: r.disputeId, status: r.status, reason: r.reason, due: r.dueAt })),
  provideDisputeEvidence: traced('PayPal: dispute response sent', provideDisputeEvidence, (r, a) => ({ dispute: a.disputeId, evidence: a.evidenceType, file: a.pdf ? 'booking-timeline.pdf' : 'none' })),
  acceptDisputeClaim: traced('PayPal: dispute claim accepted', acceptDisputeClaim, (r, a) => ({ dispute: a.disputeId })),
  sandboxDispute: traced('PayPal (sandbox): dispute moved on', sandboxDispute, (r, a) => ({ dispute: a.disputeId, action: a.action })),
  getMerchantStatus, authAssertion,
  _resetTokenCache
}
